using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class WinterTown170 {
 const string D="Assets/Events/NewYear/WinterTown170";static Material[] wraps; static Transform root,deco;static Material snow,red,gold,green,dark,orange,bulb;static int trees,snowmen,patches;static System.Random rng=new System.Random(169);
 static Transform Node(string n,Transform p,Vector3 pos){var g=new GameObject(n);g.transform.SetParent(p,false);g.transform.localPosition=pos;return g.transform;}
 static Transform Shape(string n,Transform p,PrimitiveType type,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(type);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g.transform;}
 static Bounds LocalBounds(Transform o){bool first=true;var b=new Bounds();foreach(var mf in o.GetComponentsInChildren<MeshFilter>()){var rr=mf.GetComponent<Renderer>();if(!rr||!rr.enabled||!rr.gameObject.activeInHierarchy)continue;foreach(var v in mf.sharedMesh.vertices){var p=root.InverseTransformPoint(mf.transform.TransformPoint(v));if(first){b=new Bounds(p,Vector3.zero);first=false;}else b.Encapsulate(p);}}return b;}
 static void Snow(Transform p,Vector3 pos,Vector3 size){Shape("Snow_Drift",p,PrimitiveType.Sphere,pos,size,snow);patches++;}
 static void Gift(Transform p,Vector3 pos,float size){var g=Node("Gift",p,pos);Shape("Box",g,PrimitiveType.Cube,Vector3.up*size*.4f,new Vector3(size,size*.8f,size),wraps[rng.Next(wraps.Length)]);Shape("Ribbon",g,PrimitiveType.Cube,Vector3.up*size*.41f,new Vector3(size*1.02f,size*.84f,size*.12f),gold);Shape("Cross_Ribbon",g,PrimitiveType.Cube,Vector3.up*size*.41f,new Vector3(size*.12f,size*.84f,size*1.02f),gold);}
 static void Tree(Transform p,Vector3 pos,float height){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Events/NewYear/NY_FestiveFir.prefab");var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab,p);o.name="Town_Festive_Fir";o.transform.localPosition=Vector3.zero;var b=LocalBounds(o.transform);o.transform.localScale*=height/b.size.y;b=LocalBounds(o.transform);o.transform.localPosition+=pos-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var c in o.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);trees++;Snow(p,pos+Vector3.up*.12f,new Vector3(height*.7f,.35f,height*.6f));Gift(p,pos+new Vector3(1,0,.8f),1.1f);Gift(p,pos+new Vector3(-1.2f,0,.3f),.8f);}
 static void Snowman(Transform p,Vector3 pos,float yaw){var g=Node("Snowman",p,pos);g.localRotation=Quaternion.Euler(0,yaw,0);Shape("Body",g,PrimitiveType.Sphere,new Vector3(0,.75f,0),new Vector3(1.8f,1.6f,1.65f),snow);Shape("Chest",g,PrimitiveType.Sphere,new Vector3(0,1.65f,0),new Vector3(1.35f,1.25f,1.3f),snow);Shape("Head",g,PrimitiveType.Sphere,new Vector3(0,2.45f,0),Vector3.one*1.05f,snow);Shape("Hat_Brim",g,PrimitiveType.Cylinder,new Vector3(0,2.98f,0),new Vector3(1.4f,.06f,1.4f),dark);Shape("Hat",g,PrimitiveType.Cylinder,new Vector3(0,3.25f,0),new Vector3(.85f,.26f,.85f),dark);Shape("Hat_Ribbon",g,PrimitiveType.Cylinder,new Vector3(0,3.07f,0),new Vector3(.87f,.07f,.87f),red);Shape("Scarf",g,PrimitiveType.Cylinder,new Vector3(0,2.05f,0),new Vector3(1.2f,.12f,1.2f),red);Shape("Scarf_Tail",g,PrimitiveType.Cube,new Vector3(.3f,1.65f,.62f),new Vector3(.24f,.7f,.1f),red);foreach(float x in new[]{-.18f,.18f})Shape("Eye",g,PrimitiveType.Sphere,new Vector3(x,2.55f,.48f),Vector3.one*.12f,dark);var nose=Shape("Carrot",g,PrimitiveType.Cube,new Vector3(0,2.4f,.67f),new Vector3(.14f,.14f,.5f),orange);nose.localRotation=Quaternion.Euler(0,0,45);for(int i=0;i<3;i++)Shape("Button",g,PrimitiveType.Sphere,new Vector3(0,1.65f-i*.3f,.68f),Vector3.one*.13f,dark);snowmen++;}
 static void Garland(Transform p,Vector3 a,Vector3 b,int count){var previous=a;for(int i=0;i<=count;i++){float f=i/(float)count;var q=Vector3.Lerp(a,b,f)-Vector3.up*Mathf.Sin(f*Mathf.PI)*.65f;Shape("Warm_Festive_Bulb",p,PrimitiveType.Sphere,q,Vector3.one*.3f,i%3==0?red:bulb);if(i>0){var delta=q-previous;var o=Shape("Garland_Cord",p,PrimitiveType.Cube,(q+previous)*.5f,new Vector3(.045f,.045f,delta.magnitude),dark);o.localRotation=Quaternion.LookRotation(delta);}previous=q;}}
 static string Fingerprint(GameObject o){return string.Join("\n",o.GetComponentsInChildren<MonoBehaviour>(true).Where(c=>c).Select(c=>c.GetType().FullName+":"+EditorJsonUtility.ToJson(c)))+"\nCOLLIDERS="+string.Join(";",o.GetComponentsInChildren<Collider>(true).Select(c=>EditorJsonUtility.ToJson(c)));}
 static void Batch(Transform category){var filters=category.GetComponentsInChildren<MeshFilter>().Where(m=>m.GetComponent<MeshRenderer>()!=null&&m.gameObject.activeInHierarchy).ToArray();var batches=new Dictionary<Material,List<CombineInstance>>();foreach(var mf in filters){var r=mf.GetComponent<MeshRenderer>();for(int i=0;i<mf.sharedMesh.subMeshCount;i++){var mat=r.sharedMaterials[Math.Min(i,r.sharedMaterials.Length-1)];if(!batches.ContainsKey(mat))batches[mat]=new List<CombineInstance>();batches[mat].Add(new CombineInstance{mesh=mf.sharedMesh,subMeshIndex=i,transform=category.worldToLocalMatrix*mf.transform.localToWorldMatrix});}}var children=category.Cast<Transform>().ToArray();foreach(var kv in batches){var m=new Mesh();m.name=category.name+"_"+kv.Key.name;m.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;m.CombineMeshes(kv.Value.ToArray(),true,true);AssetDatabase.CreateAsset(m,D+"/"+m.name+".asset");var node=Node(m.name,category,Vector3.zero);node.gameObject.AddComponent<MeshFilter>().sharedMesh=m;node.gameObject.AddComponent<MeshRenderer>().sharedMaterial=kv.Key;}foreach(var t in children)UnityEngine.Object.DestroyImmediate(t.gameObject);}
 public static string Main(){if(AssetDatabase.IsValidFolder(D))throw new Exception("Resources exist");Directory.CreateDirectory(D);AssetDatabase.Refresh();snow=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Snow.mat");red=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Ruby.mat");green=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Fir.mat");gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Gold.mat");dark=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/WinterTown169/Charcoal.mat");bulb=AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/WinterTown169/Warm_Light.mat");var blue=new Material(red);blue.color=new Color(.08f,.35f,.8f);AssetDatabase.CreateAsset(blue,D+"/Gift_Blue.mat");var violet=new Material(red);violet.color=new Color(.46f,.12f,.65f);AssetDatabase.CreateAsset(violet,D+"/Gift_Violet.mat");wraps=new[]{red,green,blue,violet,gold};
 var path="Assets/Events/NewYear/NY_Castle.prefab";var o=PrefabUtility.LoadPrefabContents(path);try{root=o.transform;var before=Fingerprint(o);int walls=0;var sourceTransforms=root.Cast<Transform>().Where(t=>t.name!="Visual"&&!t.name.StartsWith("NewYear")&&!t.name.StartsWith("WinterTown")).ToArray();foreach(var house in sourceTransforms){foreach(var mf in house.GetComponentsInChildren<MeshFilter>(true)){if(!mf.GetComponents<Component>().Any(c=>c&&c.GetType().Name=="ProBuilderMesh"))continue;var renderer=mf.GetComponent<MeshRenderer>();if(renderer==null||mf.sharedMesh==null||mf.sharedMesh.vertexCount==0)throw new Exception("Missing generated wall "+mf.name);var mesh=UnityEngine.Object.Instantiate(mf.sharedMesh);mesh.name="Wall_"+walls;AssetDatabase.CreateAsset(mesh,D+"/"+mesh.name+".asset");var v=Node("Persistent_Wall_170",mf.transform,Vector3.zero);v.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;var vr=v.gameObject.AddComponent<MeshRenderer>();vr.sharedMaterials=renderer.sharedMaterials;vr.shadowCastingMode=renderer.shadowCastingMode;vr.receiveShadows=renderer.receiveShadows;renderer.enabled=false;walls++;}}
 if(walls==0)throw new Exception("No walls found");deco=Node("WinterTown_170_Additions",root,Vector3.zero);var sn=Node("Rounded_Snowdrifts",deco,Vector3.zero);var gifts=Node("Colorful_Presents",deco,Vector3.zero);var wallDecor=Node("Inner_Wall_Decor",deco,Vector3.zero);int giftCount=0;
 foreach(int side in new[]{-1,1}){
 foreach(float z in new[]{-45f,-8f,17f,45f}){for(int j=0;j<3;j++){float h=.8f+j*.35f;Snow(sn,new Vector3(side*17+(j-1)*1.9f,h*.3f,z+(j%2==0?-.9f:1.2f)),new Vector3(7.4f-j*.7f,h,6.8f-j*.5f));}Gift(gifts,new Vector3(side*17+3.8f,.15f,z-1),1.4f);Gift(gifts,new Vector3(side*17-3.4f,.12f,z+1.4f),.85f);giftCount+=2;}
 foreach(float z in new[]{-42f,-27f,-14f,0f,13f,30f,44f}){float h=.75f+(float)rng.NextDouble()*1.45f;Snow(sn,new Vector3(side*(48+(float)rng.NextDouble()*3),h*.3f,z),new Vector3(7+(float)rng.NextDouble()*4,h,5+(float)rng.NextDouble()*3));}
 foreach(float z in new[]{-8f,18f}){Snow(sn,new Vector3(side*34,.45f,z),new Vector3(13,1.5f,7));Snow(sn,new Vector3(side*39,.3f,z+2),new Vector3(8,1,6));}
 foreach(float z in new[]{-49f,-36f,-3f,24f,48f}){float x=side*(22+(float)rng.NextDouble()*3);for(int j=0;j<4;j++){float size=.55f+(float)rng.NextDouble()*1.2f;Gift(gifts,new Vector3(x+(j%2)*1.5f,.12f,z+(j/2)*1.5f),size);giftCount++;}Gift(gifts,new Vector3(x,.12f+1.25f,z),.7f);giftCount++;}
 foreach(float z in new[]{-40f,1f,36f}){Gift(gifts,new Vector3(side*13,.12f,z),.6f+(float)rng.NextDouble());giftCount++;}
 // Side inner walls: decorations stand 0.25 m in front of the stone face.
 for(int k=0;k<5;k++){float z=-42+k*21;Garland(wallDecor,new Vector3(side*57.5f,7,z-7),new Vector3(side*57.5f,7,z+7),18);var center=new Vector3(side*57.2f,5.7f,z);for(int ray=0;ray<3;ray++){var t=Shape("Wall_Snowflake",wallDecor,PrimitiveType.Cube,center,new Vector3(.12f,2.5f,.17f),snow);t.localRotation=Quaternion.Euler(ray*60,0,0);}Shape("Wall_Gold_Center",wallDecor,PrimitiveType.Sphere,center,Vector3.one*.35f,gold);}
 }
 // End wall ornaments avoid central gates and their passage.
 foreach(int side in new[]{-1,1})foreach(float x in new[]{-42f,-20f,20f,42f}){Garland(wallDecor,new Vector3(x-6,8,side*52.5f),new Vector3(x+6,8,side*52.5f),16);for(int ray=0;ray<3;ray++){var t=Shape("GateSide_Snowflake",wallDecor,PrimitiveType.Cube,new Vector3(x,6.4f,side*52.2f),new Vector3(.16f,2.4f,.12f),snow);t.localRotation=Quaternion.Euler(0,0,ray*60);}}
 foreach(var group in new[]{sn,gifts,wallDecor})Batch(group);if(Fingerprint(o)!=before)throw new Exception("Gameplay or colliders changed");PrefabUtility.SaveAsPrefabAsset(o,path);AssetDatabase.SaveAssets();string report="Persistent wall surfaces="+walls+"; additional rounded snowdrifts="+patches+"; additional colorful gifts="+giftCount+"; new decor renderers="+deco.GetComponentsInChildren<Renderer>().Length+"; gameplay/collider fingerprint unchanged.";File.WriteAllText("Docs/locations/previews/winter-town170-verification.txt",report);return report;}finally{PrefabUtility.UnloadPrefabContents(o);}}
